// Everything tunable in one node, so nothing downstream needs editing.
return [{ json: {
  crew: 'BOYS',
  crew_size: 4,
  home: { name: 'Karratha', lat: -20.736, lon: 116.846 },
  ramp: { name: 'the ramp', lat: -20.62, lon: 117.19 },
  gate: {
    max_wind_kn: 11,
    offshore_from: 45, offshore_to: 135,   // easterly quadrant = offshore on a west coast
    max_wave_m: 1.0,
    min_tide_move_m: 0.15,                 // Perth is microtidal; 0.35 could never fire
    min_hours: 4
  },
  vehicle: { l_per_100km: 14 },          // 4WD towing a boat. Be honest about it.
  bring: ['rods + tackle', 'licence', 'sunnies', 'a jumper for the run out', 'esky'],
  board_url: 'https://gone-fishing-board.vercel.app',
  pub: { name: 'the pub', phone: '+61800000000' }
} }];

// Merge the two Open-Meteo responses into one hourly series and hunt for a run of
// daylight hours where wind, swell AND tide are all good at the same time.
const cfg = $('Davo settings').first().json;
const wx = $('Wind forecast').first().json;
const mar = $('Marine forecast').first().json;
const g = cfg.gate;

const hours = wx.hourly.time.map(function (iso, i) {
  return { iso: iso, hour: parseInt(iso.slice(11, 13), 10),
           wind_kn: wx.hourly.wind_speed_10m[i],
           wind_dir: wx.hourly.wind_direction_10m[i],
           temp: wx.hourly.temperature_2m[i],
           wave_m: mar.hourly.wave_height[i],
           tide_m: mar.hourly.sea_level_height_msl[i] };
});
const good = function (h) {
  return h.hour >= 5 && h.hour <= 18 && h.wind_kn != null && h.wave_m != null
      && h.wind_kn <= g.max_wind_kn
      && h.wind_dir >= g.offshore_from && h.wind_dir <= g.offshore_to
      && h.wave_m <= g.max_wave_m;
};

// EVERY unbroken run, not just the longest: one tide-dead window must not veto a
// perfectly fishable one later in the week.
const runs = []; let run = [];
hours.forEach(function (h) { if (good(h)) run.push(h); else { if (run.length) runs.push(run); run = []; } });
if (run.length) runs.push(run);

const swing = function (r) {
  const t = r.map(function (x) { return x.tide_m; }).filter(function (x) { return x != null; });
  return t.length ? Math.max.apply(null, t) - Math.min.apply(null, t) : 0;
};
const longEnough = runs.filter(function (r) { return r.length >= g.min_hours; });
const fishable = longEnough.filter(function (r) { return swing(r) >= g.min_tide_move_m; });

if (!fishable.length) {
  return [{ json: { window_on: false,
    reason: longEnough.length ? 'tide barely moves' : 'no window',
    checked: cfg.home.name } }];
}
fishable.sort(function (a, b) { return b.length - a.length || swing(b) - swing(a); });
const best = fishable[0];
const tides = best.map(function (h) { return h.tide_m; });
const avg = function (a) { return a.reduce(function (x, y) { return x + y; }, 0) / a.length; };
const DIRS = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
let peak = 0; tides.forEach(function (v, i) { if (v > tides[peak]) peak = i; });

return [{ json: {
  window_on: true,
  place: cfg.home.name,
  date_iso: best[0].iso.slice(0, 10),
  hours: best.length,
  wind_kn: Math.round(avg(best.map(function (h) { return h.wind_kn; }))),
  wind_dir: DIRS[Math.round(avg(best.map(function (h) { return h.wind_dir; })) / 22.5) % 16],
  wave_m: +avg(best.map(function (h) { return h.wave_m; })).toFixed(1),
  temp_max: Math.round(Math.max.apply(null, best.map(function (h) { return h.temp; }))),
  tide_move_m: +swing(best).toFixed(2),
  tide_turns_iso: best[peak].iso,
  checked_at: new Date().toISOString()
} }];

// GPT-4o read the reports page. Keep it defensive: a bad reply must never stop
// the trip going out, it just means we fall back to a generic spot.
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message.content) || '';
let out;
try { out = JSON.parse(String(raw).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); }
catch (e) { out = null; }

if (!out || !out.species) {
  return [{ json: { species: 'whatever is down there', spot: 'the usual lumps',
                    depth_m: null, source: 'fallback (could not read the reports)' } }];
}
return [{ json: {
  species: String(out.species).slice(0, 60),
  spot: String(out.spot || 'the usual lumps').slice(0, 60),
  depth_m: out.depth_m || null,
  source: 'fishing reports'
} }];

// FuelWatch returns every station in WA. Keep the ones actually near the drive and
// take the cheapest. Prices are in CENTS, hence the /100.
const cfg = $('Davo settings').first().json;
const sites = Array.isArray($json) ? $json : ($json.body || []);
const A = cfg.home, B = cfg.ramp;

const km = function (lat1, lon1, lat2, lon2) {
  const R = 6371, r = Math.PI / 180;
  const a = Math.sin((lat2 - lat1) * r / 2) ** 2 +
            Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin((lon2 - lon1) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
};
// crude corridor test: within 30km of the straight line between home and the ramp
const near = sites.filter(function (s) {
  const ad = s.address || {};
  if (!ad.latitude || !s.product || !s.product.priceToday) return false;
  if (s.isClosedNow) return false;
  const dA = km(A.lat, A.lon, ad.latitude, ad.longitude);
  const dB = km(B.lat, B.lon, ad.latitude, ad.longitude);
  const direct = km(A.lat, A.lon, B.lat, B.lon);
  return (dA + dB) < direct + 60;         // detour of less than ~60km total
});
near.sort(function (a, b) { return a.product.priceToday - b.product.priceToday; });

if (!near.length) {
  return [{ json: { servo: null, fuel_per_l: null, note: 'no FuelWatch site on this run' } }];
}
const best = near[0];
const avg = near.reduce(function (n, s) { return n + s.product.priceToday; }, 0) / near.length;
return [{ json: {
  servo: best.siteName,
  suburb: (best.address.location || '').replace(/\b\w/g, function (c) { return c.toUpperCase(); }),
  brand: best.brandName,
  fuel_per_l: +(best.product.priceToday / 100).toFixed(2),
  cheaper_by_c: Math.round(avg - best.product.priceToday),
  considered: near.length
} }];

const cfg = $('Davo settings').first().json;
const w = $('Score the window').first().json;
const f = $('Cheapest servo on the run').first().json;
const route = $('Route to the ramp').first().json;

// OSRM gives metres and seconds off the real road network.
const r0 = (route.routes && route.routes[0]) || {};
const km = r0.distance ? r0.distance / 1000 : 0;
const drive_min = r0.duration ? Math.round(r0.duration / 60) : 0;

const perL = f.fuel_per_l || 2.10;
const litres = km * 2 * cfg.vehicle.l_per_100km / 100;
const fuel = Math.round(litres * perL);

const turn = new Date(w.tide_turns_iso);
const leave = new Date(turn.getTime() - (drive_min + 45) * 60000);
const wake = new Date(leave.getTime() - 30 * 60000);
const hhmm = function (d) {
  let h = d.getHours(); const m = String(d.getMinutes()).padStart(2, '0');
  const ap = h < 12 ? 'am' : 'pm'; h = h % 12 || 12; return h + ':' + m + ap;
};

return [{ json: {
  km: +km.toFixed(1), drive_min: drive_min,
  fuel_cost: fuel, fuel_each: Math.ceil(fuel / Math.max(1, cfg.crew_size)),
  bait_cost: 9.90, ice_cost: 16.50, pie_rating: 4.8,
  wake_at: hhmm(wake), leave_at: hhmm(leave), launch_at: hhmm(turn),
  leave_iso: leave.toISOString()
} }];

const cfg = $('Davo settings').first().json;
const w = $('Score the window').first().json;
const b = $('What is biting').first().json;
const f = $('Cheapest servo on the run').first().json;
const r = $('Price the run').first().json;

const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const d = new Date(w.date_iso + 'T00:00:00');
const when = DAYS[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS[d.getMonth()];

// SWELL EVENT format: hook in the title line, then one "Icon Label: value" row per
// thing. On screen for under two seconds, so a labelled row beats a run of values.
const lines = [
  '\u{1F3A3} <b>GONE FISHING</b> \u2014 the window just opened',
  '',
  '\u{1F32C} <b>Forecast:</b> ' + w.wind_kn + 'kn ' + w.wind_dir + ', ' + w.wave_m + 'm, glassy',
  '\u{1F6A4} <b>Launch:</b> ' + r.launch_at + ' off ' + cfg.ramp.name + ' \u00b7 wheels ' + r.leave_at,
  '\u{1F41F} <b>Biting:</b> ' + b.species + (b.spot ? ' \u00b7 ' + b.spot : ''),
  '\u26FD <b>Fuel:</b> $' + (f.fuel_per_l || '?') + '/L at ' + (f.servo || 'the servo') +
    (f.cheaper_by_c ? ' (' + f.cheaper_by_c + 'c under)' : ''),
  '\u{1F6D2} <b>Stop:</b> bait $' + r.bait_cost.toFixed(2) + ' \u00b7 ice $' + r.ice_cost.toFixed(2) +
    ' \u00b7 pie ' + r.pie_rating + '\u2605',
  '\u{1F4B0} <b>Split:</b> $' + r.fuel_each + ' each \u00b7 ' + r.km + 'km',
  '\u{1F3C6} <b>Board:</b> <a href="' + cfg.board_url + '">live leaderboard</a>',
  '',
  '\u{1F447} Boys \u2014 ' + when + '. You in?'
];
return [{ json: {
  text: lines.join('\n'),
  poll_question: 'Catch fish or fold washing?',
  trip: { date_iso: w.date_iso, place: w.place, leave_at: r.leave_at, launch_at: r.launch_at,
          species: b.species, spot: b.spot, fuel_each: r.fuel_each, km: r.km,
          leave_iso: r.leave_iso, status: 'proposed' }
} }];

// Telegram poll_answer webhook. option_ids [0] is "I'm in".
const b = $json.body || $json;
const a = b.poll_answer || {};
const inIt = Array.isArray(a.option_ids) && a.option_ids.indexOf(0) !== -1;
const who = (a.user && (a.user.first_name || a.user.username)) || 'someone';
return [{ json: { in: inIt, who: who, user_id: a.user && a.user.id } }];

const t = $('Load the trip').first().json;
const trip = Array.isArray(t) ? t[0] : t;
const me = $('Who tapped in').first().json;
const bring = ['rods + tackle', 'licence', 'sunnies', 'a jumper for the run out', 'esky'];

const lines = [
  '\u{1F3A3} <b>' + me.who + ", you're in.</b>",
  '',
  '\u23F0 <b>Alarm:</b> ' + (trip.wake_at || '4:00am') + ' \u00b7 wheels ' + trip.leave_at,
  '\u{1F6A4} <b>Launch:</b> ' + trip.launch_at + ' \u00b7 ' + trip.km + 'km',
  '\u{1F41F} <b>Target:</b> ' + trip.species + ' \u00b7 ' + trip.spot,
  '\u{1F4B0} <b>Your share:</b> $' + trip.fuel_each,
  '',
  '<b>Bring:</b> ' + bring.join(', ') + '.',
  '',
  '\u{1F4F8} Photo every fish and send it to me. It goes on the board or it did not happen.'
];
return [{ json: { text: lines.join('\n'), who: me.who } }];

// OwnTracks posts {lat, lon, tst}. An iOS Shortcut can post the same shape.
// Apple exposes NO Find My API and never has, so this is the workaround: it is
// free, open source, and takes about five minutes on the phone.
const b = $json.body || $json;
const lat = Number(b.lat != null ? b.lat : b.latitude);
const lon = Number(b.lon != null ? b.lon : b.longitude);
const ramp = { lat: -30.3050, lon: 115.0393 };

const km = function (a, b2, c, d) {
  const R = 6371, r = Math.PI / 180;
  const x = Math.sin((c - a) * r / 2) ** 2 +
            Math.cos(a * r) * Math.cos(c * r) * Math.sin((d - b2) * r / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x));
};
const dist = km(lat, lon, ramp.lat, ramp.lon);

// "heading in" = inside 8km of the ramp and closer than the last ping we saw
const prev = Number(b.prev_km || 999);
const heading_in = dist < 8 && dist < prev;

return [{ json: { lat: lat, lon: lon, km_to_ramp: +dist.toFixed(2),
                  heading_in: heading_in, eta_min: Math.round(dist / 25 * 60) } }];

const h = $('Where is the boat' ).first().json;
return [{ json: {
  phone: '+61800000000',
  task: 'You are calling on behalf of a group of four coming off the water. Ask them to '
      + 'hold a table for four in about ' + (h.eta_min + 25) + ' minutes, and to have four '
      + 'cold beers poured for when they walk in. Be brief and friendly.',
  eta_min: h.eta_min + 25
} }];

// The model is told to return bare JSON; models fence it anyway. Strip, then parse,
// and never let a bad reply kill the run.
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message.content) || '';
let fish;
try { fish = JSON.parse(String(raw).replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); }
catch (e) { return [{ json: { ok: false, reason: 'could not read the model reply' } }]; }
const hook = $('Webhook: a fish').first().json.body || {};
const len = Number(fish.length_cm);
if (!fish.species || String(fish.species).toLowerCase() === 'not a fish')
  return [{ json: { ok: false, reason: 'that is not a fish', angler: hook.angler } }];
if (!isFinite(len) || len <= 0 || len > 400)
  return [{ json: { ok: false, reason: 'could not size it', angler: hook.angler } }];
return [{ json: { ok: true, angler: hook.angler, group_code: hook.group_code || 'BOYS',
                  species: String(fish.species).slice(0, 40), length_cm: Math.round(len),
                  note: fish.note || '' } }];

const c = $('Read the fish').first().json;
if (!c.ok) return [{ json: { text: '\u{1F440} Davo had a look and ' + (c.reason || 'could not tell') + '. Send another photo.' } }];
const lines = [
  '\u{1F41F} <b>' + c.angler + '</b> just landed a <b>' + c.species + '</b>',
  '<b>' + c.length_cm + 'cm</b> · ' + c.length_cm + ' points',
  c.note ? '<i>' + c.note + '</i>' : '',
  '', '\u{1F3C6} Board: https://gone-fishing-board.vercel.app'
].filter(Boolean);
return [{ json: { text: lines.join('\n') } }];
